ensureFullSchema($pdo);$pageTitle='Financeiro';
$mes=$_GET['mes']??date('Y-m');if(!preg_match('/^\d{4}-\d{2}$/',$mes))$mes=date('Y-m');$inicio=$mes.'-01';$fim=date('Y-m-d',strtotime($inicio.' +1 month'));
$s=$pdo->prepare("SELECT * FROM vendas WHERE data_venda>=? AND data_venda<? ORDER BY data_venda DESC,id DESC");$s->execute([$inicio,$fim]);$vendas=$s->fetchAll();$receita=$custos=$lucro=0;$origens=[];$positivas=$negativas=0;foreach($vendas as &$v){$c=(float)$v['custo_materiais']+(float)$v['custo_tempo']+(float)$v['custo_envio']+(float)$v['outros_custos'];$l=(float)$v['receita']-$c;$v['_custo']=$c;$v['_lucro']=$l;$receita+=(float)$v['receita'];$custos+=$c;$lucro+=$l;$l>=0?$positivas++:$negativas++;if(!isset($origens[$v['origem']]))$origens[$v['origem']]=['receita'=>0,'lucro'=>0,'q'=>0];$origens[$v['origem']]['receita']+=(float)$v['receita'];$origens[$v['origem']]['lucro']+=$l;$origens[$v['origem']]['q']++;}unset($v);$margem=$receita>0?($lucro/$receita*100):0;$ticket=count($vendas)?$receita/count($vendas):0;
require __DIR__ . '/includes/header.php';
