<div class="admin-section-head"><div><span class="section-kicker">VENDA POR VENDA</span><h2>O que deu margem — e o que não deu</h2></div></div><div class="table-wrap finance-table"><table><thead><tr><th>Data</th><th>Origem</th><th>Descrição</th><th>Receita</th><th>Custo</th><th>Lucro</th><th>Margem</th><th></th></tr></thead><tbody id="financeTableBody"><?php foreach($vendas as $v): $mg=(float)$v['receita']>0?$v['_lucro']/(float)$v['receita']*100:0; ?><tr class="<?= $v['_lucro']>=0?'row-green':'row-red' ?>"><td><?= date('d/m',strtotime($v['data_venda'])) ?></td><td><?= e($v['origem']) ?></td><td><strong><?= e($v['descricao']) ?></strong><small><?= e($v['cliente']) ?></small></td><td><?= dinheiro($v['receita']) ?></td><td><?= dinheiro($v['_custo']) ?></td><td><strong><?= dinheiro($v['_lucro']) ?></strong></td><td><?= number_format($mg,1,',','.') ?>%</td><td><a class="table-link" href="<?= BASE_URL ?>/admin/venda.php?id=<?= (int)$v['id'] ?>">Editar</a></td></tr><?php endforeach; ?><?php if(!$vendas): ?><tr id="financeEmpty"><td colspan="8" class="empty-cell">Ainda não há vendas registradas neste mês.</td></tr><?php endif; ?></tbody></table></div>

